package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.*;import jakarta.persistence.*;@Entity@Table(name="chamados")public class Chamado extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;private int numeroMesa;@Enumerated(EnumType.STRING)private TipoChamado tipo;@Enumerated(EnumType.STRING)private StatusChamado status=StatusChamado.ABERTO;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public int getNumeroMesa(){return numeroMesa;}public void setNumeroMesa(int v){numeroMesa=v;}public TipoChamado getTipo(){return tipo;}public void setTipo(TipoChamado v){tipo=v;}public StatusChamado getStatus(){return status;}public void setStatus(StatusChamado v){status=v;}}
